import { AlchemystAI } from '@alchemystai/sdk';
import { randomUUID } from 'node:crypto';
import fs from 'node:fs/promises';

async function run() {
  const ZEALT_RUN_ID = process.env.ZEALT_RUN_ID || 'local';
  const API_KEY = process.env.ALCHEMYST_AI_API_KEY;

  if (!API_KEY) {
    console.error('ALCHEMYST_AI_API_KEY is not set');
    process.exit(1);
  }

  const userId = `zealt-${ZEALT_RUN_ID}-${randomUUID()}`;
  const sessionA = `zealt-${ZEALT_RUN_ID}-${randomUUID()}`;
  const sessionB = `zealt-${ZEALT_RUN_ID}-${randomUUID()}`;
  const query = "What is the user's preferred coding language?";

  console.log(`userId: ${userId}`);
  console.log(`sessionA: ${sessionA}`);
  console.log(`sessionB: ${sessionB}`);

  const client = new AlchemystAI({ apiKey: API_KEY });

  // Step 1: Add memory in session A
  console.log('Adding memory in session A...');
  const content = `User ${userId}'s preferred coding language is Rust.`;
  await client.v1.context.memory.add({
    sessionId: sessionA,
    contents: [{ content }]
  });
  console.log('Memory added.');

  // Step 2: Search from session B with retries
  console.log('Waiting for indexing...');
  let contexts: any[] = [];
  const maxRetries = 10;
  const retryDelay = 5000; // 5 seconds

  for (let i = 0; i < maxRetries; i++) {
    console.log(`Search attempt ${i + 1}/${maxRetries}...`);
    const response = await client.v1.context.search({
      query,
      scope: 'internal',
      similarity_threshold: 0.8,
      minimum_similarity_threshold: 0.5
    });

    contexts = response.contexts || [];

    const found = contexts.some(ctx => ctx.content?.includes('Rust') && ctx.content?.includes(userId));
    if (found) {
      console.log('Memory recalled successfully!');
      break;
    }

    if (i < maxRetries - 1) {
      console.log(`Not found yet, waiting ${retryDelay / 1000}s...`);
      await new Promise(resolve => setTimeout(resolve, retryDelay));
    }
  }

  const result = {
    userId,
    sessionA,
    sessionB,
    query,
    contexts
  };

  await fs.writeFile('/workspace/recall.json', JSON.stringify(result, null, 2));
  console.log('Result written to /workspace/recall.json');

  const hasRust = contexts.some(ctx => ctx.content?.includes('Rust'));
  if (!hasRust) {
    console.error('Failed to recall memory containing "Rust"');
    process.exit(1);
  }
}

run().catch(err => {
  console.error('Error during execution:', err);
  process.exit(1);
});
